function EXTRA(R,ICON){
 /* hook: a cube of room air full of molecules, and the one-number thermometer */
 ICON.thRoom=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  <rect x="18" y="18" width="134" height="134" fill="${TH_AIR}" stroke="${TH_DARK}" stroke-width="3"/>${TH_movers(28,28,110,110,9,BLU)}
  ${TH_T(172,62,'1 cm³ of air',{fs:24,fw:800,fill:BLU})}${TH_T(172,98,'2.45 × 10¹⁹',{fs:24,fw:800,fill:TH_DARK})}${TH_T(172,130,'molecules',{fs:22,fill:TH_GREY})}</g>`;
 ICON.thThermo=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  ${TH_thermo(60,22,104)}${TH_T(110,72,'one number:',{fs:24,fw:800,fill:ORG})}${TH_T(110,116,'27 °C',{fs:40,fw:800,fill:TH_DARK})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.thBand=(x,y)=>{const B=TH_band(40,250,360,220);let s=TH_arrow(40,250,420,250,TH_DARK,3,12)+TH_arrow(40,250,40,10,TH_DARK,3,12)+B.poly+TH_L(40,B.Y(1.177),400,B.Y(1.177),BLU,3,'stroke-dasharray="9 6"')+
  TH_T(400,B.Y(1.177)-12,'ρ = 1.177',{fs:22,fw:800,a:'end',fill:BLU})+TH_T(40,286,'10 nm',{fs:22,a:'middle',fill:TH_GREY})+TH_T(400,286,'10 µm',{fs:22,a:'middle',fill:TH_GREY})+TH_T(220,312,'cube size',{fs:22,a:'middle',fill:TH_GREY});
  return `<g transform="translate(${x-220} ${y-150})">${s}</g>`};
 ICON.thTank=(x,y)=>{let s=`<rect x="40" y="40" width="220" height="200" rx="26" fill="${TH_AIR}" stroke="${TH_STEEL}" stroke-width="7"/>`+TH_dots(66,66,170,150,18,BLU,6)+
  `<rect x="24" y="24" width="252" height="232" rx="34" fill="none" stroke="${ORG}" stroke-width="4" ${TH_DASH}/>`+TH_L(260,90,300,90,TH_DARK,6)+TH_arrow(300,90,390,90,BLU,5,16)+TH_T(345,74,'mass',{fs:22,fw:800,a:'middle',fill:BLU})+
  TH_arrow(150,262,150,318,ORG,5,16)+TH_T(170,306,'heat',{fs:22,fw:800,fill:ORG});
  return `<g transform="translate(${x-210} ${y-160})">${s}</g>`};
 ICON.thLoop=(x,y)=>{const F=TH_pv(50,280,320,250),X=F.X,Y=F.Y,pts=TH_ST.concat([TH_ST[0]]).map(([V,p])=>[X(V),Y(p)]);
  let s=F.ax+`<rect x="${X(0.20)}" y="${Y(200)}" width="${X(0.30)-X(0.20)}" height="${Y(100)-Y(200)}" fill="${GRN}" fill-opacity=".25"/>`+TH_poly(pts,GRN,5)+
  TH_ST.map(([V,p],i)=>`<circle cx="${X(V)}" cy="${Y(p)}" r="9" fill="${TH_DARK}"/>`+TH_T(X(V)+(i<2?-14:14),Y(p)+(i%3?-14:30),String(i+1),{fs:24,fw:800,a:i<2?'end':'start',fill:TH_DARK})).join('')+
  TH_T(X(0.25),Y(150)+10,'10 kJ',{fs:28,fw:800,a:'middle',fill:GRN});
  return `<g transform="translate(${x-200} ${y-150})">${s}</g>`};
}
